sp_widget.client_script:
api.controller = function() {
  var c = this;
  c.description = '';
  c.quantity = 1;
  c.statusMessage = '';

  c.findMatches = function() {
    c.statusMessage = '';
    if (!c.description || !c.description.trim()) return;
    c.server.get({
      action: 'search',
      query: c.description
    }).then(function(res) {
      c.data = res.data;
    });
  };

  c.getSelectedPart = function() {
    if (!c.data || !c.data.matches) return null;
    return c.data.matches.find(function(m) {
      return m.sys_id === c.data.selectedPartId;
    }) || null;
  };

  c.getStockLabel = function() {
    var part = c.getSelectedPart();
    if (!part) return 'No Part Selected';
    if (part.stock_quantity <= 0) return 'Out of Stock';
    if (c.quantity > part.stock_quantity) return 'Exceeds Stock (' + part.stock_quantity + ' available)';
    if (part.stock_quantity - c.quantity <= part.reorder_threshold) return 'Will Trigger Low Stock / Reorder';
    return 'In Stock';
  };

  c.submitRequest = function() {
    var selected = c.getSelectedPart();
    if (!selected) return;

    c.server.get({
      action: 'submit_request',
      rawDescription: c.description,
      selectedPartId: selected.sys_id,
      ambiguityFlag: c.data.ambiguityFlag,
      confidenceScore: c.data.confidenceScore,
      candidates: c.data.matches,
      quantity: c.quantity
    }).then(function(res) {
      c.data = res.data;
      c.description = '';
      c.quantity = 1;
      c.statusMessage = 'Submitted request: ' + (c.data.submittedNumber || 'Saved');
    });
  };
};

sp_widget.script:
(function() {
  var PART_TABLE = 'x_2323667_intell_0_spare_parts_catalog';
  var REQ_TABLE  = 'x_2323667_intell_0_spare_parts_request';

  if (!input) {
    data.myRequests = getRecentRequests(REQ_TABLE);
    return;
  }

  if (input.action === 'search') {
    var query = (input.query || '').toLowerCase().trim();
    var tokens = query.split(/[^a-z0-9]+/).filter(function(t) { return t.length > 1; });
    var candidates = [];

    var gr = new GlideRecord(PART_TABLE);
    gr.query();
    while (gr.next()) {
      var partNumber = gr.getValue('number') || '';
      var partName   = gr.getValue('part_name') || '';
      var aliases    = gr.getValue('description_aliases') || '';
      var category   = gr.getValue('category') || '';
      var stock      = parseInt(gr.getValue('stock_quantity'), 10) || 0;
      var reorder    = parseInt(gr.getValue('reorder_threshold'), 10) || 0;
      var unitCost   = parseFloat(gr.getValue('unit_cost')) || 0;

      var haystack = (partNumber + ' ' + partName + ' ' + aliases + ' ' + category).toLowerCase();
      var score = 0;

      if (query && haystack.indexOf(query) !== -1) {
        score += 10;
      }
      tokens.forEach(function(tok) {
        if (partNumber.toLowerCase().indexOf(tok) !== -1) score += 6;
        if (partName.toLowerCase().indexOf(tok) !== -1) score += 4;
        if (aliases.toLowerCase().indexOf(tok) !== -1) score += 3;
        if (category.toLowerCase().indexOf(tok) !== -1) score += 2;
      });

      if (score > 0) {
        candidates.push({
          sys_id: gr.getUniqueValue(),
          part_number: partNumber,
          part_name: partName,
          category: category,
          stock_quantity: stock,
          reorder_threshold: reorder,
          unit_cost: unitCost,
          score: score
        });
      }
    }

    candidates.sort(function(a, b) { return b.score - a.score; });
    var top = candidates.slice(0, 5);

    var isAmbiguous = false;
    var confidence = 0;
    var selectedId = '';

    if (top.length === 1 && top[0].score >= 4) {
      confidence = Math.min(99, top[0].score * 10);
      selectedId = top[0].sys_id;
    } else if (top.length > 1) {
      var gap = top[0].score - top[1].score;
      confidence = Math.min(95, Math.max(25, top[0].score * 8));
      isAmbiguous = !(top[0].score >= 8 && gap >= 5);
      selectedId = top[0].sys_id;
    }

    data.matches = top;
    data.searched = true;
    data.ambiguityFlag = isAmbiguous;
    data.confidenceScore = confidence;
    data.selectedPartId = selectedId;
  }

  if (input.action === 'submit_request') {
    var candidateSummary = (input.candidates || []).map(function(c) {
      return (c.part_number ? c.part_number + ': ' : '') + c.part_name + ' (Stock: ' + c.stock_quantity + ')';
    }).join(' | ');

    var reqGr = new GlideRecord(REQ_TABLE);
    reqGr.initialize();
    reqGr.setValue('technician_description', input.rawDescription || '');
    reqGr.setValue('matched_part', input.selectedPartId || '');
    reqGr.setValue('candidate_options', candidateSummary);
    reqGr.setValue('ai_confidence_score', parseInt(input.confidenceScore, 10) || 0);
    reqGr.setValue('ambiguity_flag', Boolean(input.ambiguityFlag));
    reqGr.setValue('technician_confirmed', true);
    reqGr.setValue('quantity_requested', parseInt(input.quantity, 10) || 1);

    var createdId = reqGr.insert();

    data.submittedNumber = createdId ? (reqGr.getDisplayValue('number') || reqGr.getUniqueValue().slice(0, 8)) : '';
    data.matches = [];
    data.searched = false;
    data.myRequests = getRecentRequests(REQ_TABLE);
  }

  function getRecentRequests(tableName) {
    var list = [];
    var rGr = new GlideRecord(tableName);
    rGr.orderByDesc('sys_created_on');
    rGr.setLimit(10);
    rGr.query();
    while (rGr.next()) {
      var ambVal = rGr.getValue('ambiguity_flag');
      var confVal = rGr.getValue('technician_confirmed');
      list.push({
        number: rGr.getDisplayValue('number') || rGr.getUniqueValue().slice(0, 8),
        description: rGr.getValue('technician_description') || '',
        matched_part: rGr.getDisplayValue('matched_part') || 'Unmatched',
        confidence: parseInt(rGr.getValue('ai_confidence_score'), 10) || 0,
        ambiguous: ambVal === '1' || ambVal === 'true',
        confirmed: confVal === '1' || confVal === 'true',
        quantity: parseInt(rGr.getValue('quantity_requested'), 10) || 0
      });
    }
    return list;
  }
})();
